package com.example.dsatracker.service;import com.example.dsatracker.dto.SubmissionRequestDTO;import com.example.dsatracker.dto.SubmissionResponseDTO;import com.example.dsatracker.exception.ResourceNotFoundException;import com.example.dsatracker.mapper.SubmissionMapper;import com.example.dsatracker.model.Problem;import com.example.dsatracker.model.Submission;import com.example.dsatracker.model.User;import com.example.dsatracker.repository.ProblemRepository;import com.example.dsatracker.repository.SubmissionRepository;import com.example.dsatracker.repository.UserRepository;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.stereotype.Service;import java.time.LocalDateTime;@Servicepublic class SubmissionService {    private final SubmissionRepository submissionRepository;    private final ProblemRepository problemRepository;    private final UserRepository userRepository;    public SubmissionService(            SubmissionRepository submissionRepository,            ProblemRepository problemRepository,            UserRepository userRepository) {        this.submissionRepository = submissionRepository;        this.problemRepository = problemRepository;        this.userRepository = userRepository;    }    public SubmissionResponseDTO createSubmission(            SubmissionRequestDTO request) {        String email = SecurityContextHolder                .getContext()                .getAuthentication()                .getName();        User user = userRepository.findByEmail(email)                .orElseThrow(() ->                        new ResourceNotFoundException("User not found"));        Problem problem = problemRepository                .findById(request.getProblemId())                .orElseThrow(() ->                        new ResourceNotFoundException("Problem not found"));        Submission submission =                SubmissionMapper.toEntity(request);        submission.setUser(user);        submission.setProblem(problem);        int revisionDays = calculateRevisionDays(                request.getConfidenceScore());        submission.setNextRevision(                LocalDateTime.now().plusDays(revisionDays));        Submission savedSubmission =                submissionRepository.save(submission);        return SubmissionMapper.toResponse(savedSubmission);    }    private int calculateRevisionDays(int score) {        if (score >= 90) {            return 10;        } else if (score >= 70) {            return 5;        } else if (score >= 40) {            return 2;        }        return 1;    }}